// Calls fn up to `times` attempts, returning the first success.
function retry(fn, times) {
  // Retry on error; rethrow the last error if every attempt fails.
  // Track the most recent failure.
  let lastError;
  for (let i = 0; i < times; i++) {
    try { return fn(); } catch (err) { lastError = err; }
  }
  throw lastError;
}

