// Returns a wrapper that caches fn's results by argument.
function memoize(fn) {
  // Storage for previously computed results.
  const cache = new Map();
  return function (arg) {
    // Compute once per argument; reuse the stored value afterward.
    if (!cache.has(arg)) cache.set(arg, fn.call(this, arg));
    return cache.get(arg);
  };
}

